type Subject struct {
	listeners map[int]func(int)
	next      int
}

func (s *Subject) Subscribe(f func(int)) func() {
	id := s.next
	s.next++
	s.listeners[id] = f
	return func() { delete(s.listeners, id) }
}
func (s *Subject) Notify(n int) {
	for _, f := range s.listeners {
		f(n)
	}
}

func main() {
	s := Subject{listeners: make(map[int]func(int))}
	total := 0
	stop := s.Subscribe(func(n int) { total += n })
	s.Notify(3)
	stop()
	s.Notify(5)
	fmt.Println(total)
}

// Output:
// 3

