func Merge(inputs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	for _, input := range inputs {
		wg.Add(1)
		go func(ch <-chan int) {
			defer wg.Done()
			for n := range ch {
				out <- n
			}
		}(input)
	}
	go func() { wg.Wait(); close(out) }()
	return out
}

func main() {
	a, b := make(chan int, 2), make(chan int, 2)
	a <- 1
	a <- 2
	close(a)
	b <- 3
	b <- 4
	close(b)
	sum := 0
	for n := range Merge(a, b) {
		sum += n
	}
	fmt.Println(sum)
}

// Output:
// 10

