	done := make(chan struct{})
	go Counter(requests, done)
	reply := make(chan int)
	requests <- Add{Delta: 2, Reply: reply}
	fmt.Println(<-reply)
	requests <- Add{Delta: 3, Reply: reply}
	fmt.Println(<-reply)
	close(requests)
	<-done
