var ErrOpen = errors.New("circuit open")

type Breaker struct {
	failures int
	until    time.Time
}

func (b *Breaker) Call(now time.Time, op func() error) error {
	if now.Before(b.until) {
		return ErrOpen
	}
	err := op()
	if err == nil {
		b.failures = 0
		b.until = time.Time{}
		return nil
	}
	b.failures++
	if b.failures >= 2 {
		b.until = now.Add(time.Second)
	}
	return err
}

func main() {
	b := &Breaker{}
	now := time.Unix(0, 0)
	calls := 0
	fail := func() error { calls++; return errors.New("offline") }
	_ = b.Call(now, fail)
	_ = b.Call(now, fail)
	fmt.Println(b.Call(now, fail), calls)
	fmt.Println(b.Call(now.Add(time.Second), func() error { return nil }))
}

